function extraAtomic(value){return typeof value==='string'&&/^(0|[1-9]\d{0,39})$/.test(value)?BigInt(value):null;}
function extraUsd(value,input=false){const atoms=extraAtomic(value);if(atoms===null)return input?'':'未知';const cents=(atoms+5000000000n)/10000000000n,whole=cents/100n;return (input?'':'$')+(input?whole.toString():whole.toLocaleString('zh-CN'))+'.'+String(cents%100n).padStart(2,'0');}
function extraAmount(value,unit){const atoms=extraAtomic(value);if(atoms===null)return '未知';if(unit==='reference_usd_atoms')return extraUsd(value)+'（Standard参考估算）';return atoms.toLocaleString('zh-CN')+' '+(unit&&unit!=='unknown'?esc(unit)+'（按来源计量单位）':'（单位待确认）');}
function extraUsdInput(value){if(!/^\d{1,12}(?:\.\d{1,2})?$/.test(String(value).trim()))throw Error('USD请输入非负金额，最多两位小数');const [whole,part='']=String(value).trim().split('.');return (BigInt(whole)*1000000000000n+BigInt(part.padEnd(2,'0'))*10000000000n).toString();}
function extraIntegerInput(value,optional=false){const text=String(value??'').trim();if(optional&&!text)return null;if(!/^(0|[1-9]\d{0,39})$/.test(text))throw Error('来源单位金额请输入非负整数，留空表示未知');return text;}
function extraList(value){const values=String(value||'').split(/[,，\n]/).map(value=>value.trim()).filter(Boolean);if(!values.length||values.length>200||new Set(values).size!==values.length||values.some(value=>!(/^[a-zA-Z0-9][a-zA-Z0-9._:/-]{0,199}$/).test(value)))throw Error('请填写明确的适用范围，以逗号分隔；不使用通配符');return values;}
function extraDateInput(value){if(!value)return null;const time=Date.parse(value+'+08:00');if(!Number.isSafeInteger(time)||time<0)throw Error('有效期格式无效，请使用北京时间');return time;}
function extraNote(value){const note=String(value||'').trim();if(!note||new TextEncoder().encode(note).byteLength>2048)throw Error('说明不能为空，且不能超过2048字节（约682个汉字）');return note;}
function extraNonce(){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);return 'reset-'+Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');}
function extraDateValue(value){if(value===null||value===undefined)return '';const d=new Date(value+8*3600000);return Number.isFinite(d.getTime())?d.toISOString().slice(0,19):'';}
function extraBadge(row){return `<span class="badge ${row?.category==='allowed'?'ok':row?.category==='blocked'?'off':'warn'}">${row?.category==='allowed'?'条件具备，按请求复核':row?.category==='blocked'?'禁止额外消耗':'待配置或核验'}</span>`;}
function extraBrief(row){const account=state?.accounts?.find(account=>account.id===row?.account_id);return account?extraObserved(packageQuota(account)):'<small>官方权益未知</small>';}
async function loadExtraPool(){if(!admin||tab!=='accounts'||!extraEnabled())return;const nodes=[...document.querySelectorAll('[data-extra-summary]')],ids=nodes.map(node=>node.dataset.extraSummary);if(!ids.length)return;extraPoolController?.abort();const controller=new AbortController(),version=++extraPoolVersion,epoch=authEpoch;extraPoolController=controller;try{const value=await api('/api/admin/extra-usage/coverage?'+new URLSearchParams({ids:ids.join(','),page_size:'100'}),'GET',undefined,'',controller.signal);if(!admin||epoch!==authEpoch||version!==extraPoolVersion||tab!=='accounts')return;for(const row of value.rows)extraPoolRows.set(row.account_id,row);for(const node of nodes)if(node.isConnected)node.innerHTML=extraBrief(extraPoolRows.get(node.dataset.extraSummary));}catch(error){if(!controller.signal.aborted&&admin&&epoch===authEpoch&&version===extraPoolVersion&&tab==='accounts')for(const node of nodes)if(node.isConnected)node.innerHTML='<small>权益摘要暂不可读，请打开详情重新读取</small>';}finally{if(extraPoolController===controller)extraPoolController=null;}}
function extraBudgetMarkup(budget,usage){return budget?`<p>计量依据：${budget.basis==='reference_estimate'?'Standard参考估算':'官方来源单位'}<br>一次授权预算：${extraAmount(budget.limit_atoms,budget.unit)}<br>单请求并发预留：${extraAmount(budget.request_reserve_atoms,budget.unit)}</p>${usage?`<p>累计已用：${extraAmount(usage.used_atoms,budget.unit)}<br>在途预留：${extraAmount(usage.reserved_atoms,budget.unit)}${usage.unresolved?'<br><strong>有消耗待核对，预留继续保留</strong>':''}</p>`:''}`:'<p>预算未配置，不代表无限额；历史计量继续保留。</p>'+(usage?`<p>历史已用：${extraAmount(usage.used_atoms,usage.unit)}<br>在途预留：${extraAmount(usage.reserved_atoms,usage.unit)}${usage.unresolved?'<br><strong>有消耗待核对，预留继续保留</strong>':''}</p>`:'');}
function extraBudgetFields(){return `<label>预算处理<select name="budget_change"><option value="keep">保留原精确预算</option><option value="unset">明确清除预算</option><option value="reference">重新设置参考USD估算预算</option><option value="official">重新设置官方单位预算</option></select></label><div class="extra-budget-inputs hidden"><label>官方计量单位（仅官方单位预算填写）<input name="budget_unit" maxlength="80" placeholder="按来源准确填写，不猜USD倍率"></label><div class="form-grid"><label>一次授权总预算<input name="budget_limit" inputmode="decimal" placeholder="参考USD最多两位；官方单位为整数"></label><label>单请求并发预留<input name="budget_reserve" inputmode="decimal" placeholder="必须大于0且不超过总预算"></label></div></div><p class="hint">预算由此账号全部员工共享，不随02:00或转移重置；并发预留不是实际消费或本次账单上限。参考估算不能保证上游账单金额。</p>`;}
function bindExtraBudget(form){form.elements.budget_change.onchange=()=>form.querySelector('.extra-budget-inputs').classList.toggle('hidden',['keep','unset'].includes(form.elements.budget_change.value));}
function extraBudgetPayload(form,previous,batch=false){const mode=form.get('budget_change');if(mode==='keep')return batch?{}:{budget:previous};if(mode==='unset')return {budget:null};if(!['reference','official'].includes(mode))throw Error('请选择预算处理方式');const reference=mode==='reference',unit=reference?'reference_usd_atoms':String(form.get('budget_unit')||'').trim();if(!/^[a-zA-Z0-9][a-zA-Z0-9._:/-]{0,79}$/.test(unit))throw Error('请准确填写官方计量单位');const limit=reference?extraUsdInput(form.get('budget_limit')):extraIntegerInput(form.get('budget_limit')),reserve=reference?extraUsdInput(form.get('budget_reserve')):extraIntegerInput(form.get('budget_reserve'));if(BigInt(reserve)<=0n||BigInt(reserve)>BigInt(limit))throw Error('并发预留必须大于0且不超过总预算');return {budget:{basis:reference?'reference_estimate':'official',unit,limit_atoms:limit,request_reserve_atoms:reserve}};}
function openExtraView(kind,title,id=''){modal(`<h2>${esc(title)}</h2><div id="extra-content">正在读取…</div>`,true);$('#modal').classList.add('extra-dialog');const view={kind,id,epoch:authEpoch,dialog:dialogVersion,controller:new AbortController(),busy:false,loading:false,error:'',conflicted:false};extraView=view;return view;}
function extraEndpoint(view,suffix=''){return '/api/admin/accounts/'+encodeURIComponent(view.id)+'/extra-usage'+suffix;}
async function loadExtraAccount(view){if(!extraCurrent(view)||view.loading)return;view.loading=true;try{const [data,records]=await Promise.all([api(extraEndpoint(view),'GET',undefined,'',view.controller.signal),api(extraEndpoint(view,'/records?limit=20'),'GET',undefined,'',view.controller.signal)]);if(!extraCurrent(view))return;Object.assign(view,{data,records,error:'',conflicted:false});renderExtraAccount(view);}catch(error){if(extraCurrent(view)){view.error=error.message;renderExtraAccount(view);}}finally{view.loading=false;}}
function extraObserved(quota){
 const observation=quota?.entitlements,credits=observation?.credits,cards=observation?.reset_cards,count=cards?.remaining,known=Number.isSafeInteger(count)&&count>=0;
 return `<div class="official-extra-summary"><p>额外额度：<strong>${credits?.balance==null?'官方未提供':decimal(credits.balance)+'（官方来源单位）'}</strong></p><p>重置卡：<strong>${known?fmt(count)+' 张':'官方未提供数量'}</strong></p>${observation?.checked?`<p class="hint">官方更新：${beijingDate(observation.checked)}</p>`:''}${cards?.cards?.length?`<details><summary>查看官方卡详情</summary>${cards.cards.map(card=>`<article class="extra-record"><strong>${esc(card.title||'重置卡')}</strong><p>${esc(card.description||'')}<br>状态：${esc(({available:'可用',redeeming:'使用中',redeemed:'已使用',unknown:'未知'})[card.status]||card.status)}<br>有效期：${card.expiry_known?(card.expires_at===null?'未设到期':beijingDate(card.expires_at)):'官方未提供'}<br>适用窗口：${esc(card.windows?.join('、')||'官方未提供')}</p></article>`).join('')}</details>`:''}<p class="hint">重置卡请在官方页面使用，Harbor 暂无直接兑换接口。</p></div>`;
}
function extraScope(e){return `<p>适用模型：${esc(e?.models?.join('、')||'未知')}<br>适用协议：${esc(e?.protocols?.join('、')||'未知')}<br>权益有效期：${e?.expires_at===null?'未提供':beijingDate(e?.expires_at)}</p>`;}
function extraCards(cards){return `<p>剩余：${cards?.remaining===null||cards?.remaining===undefined?'未知':fmt(cards.remaining)+' 次'}<br>有效期：${cards?.expires_at===null?'未提供':beijingDate(cards?.expires_at)}<br>可重置窗口：${esc(cards?.windows?.join('、')||'未知')}</p>`;}
function extraJobMarkup(job,error=''){if(!job)return '';const labels={queued:'等待执行',running:'读取中',completed:'读取结束',refreshed:'快照已更新',verified:'已核验',pending_verification:'待核验',rejected:'上游拒绝',failed:'读取失败',cancelled:'已取消',unsupported:'未支持',not_started:'未开始'};return `<section class="extra-section"><h3>最近刷新任务</h3>${error?`<p class="notice warn">任务状态暂不可读：${esc(error)}。已保留原任务，不重复创建刷新。</p>${button('extra-refresh-retry','重试查询此任务','secondary')}`:''}<p>${esc(labels[job.state]||job.state)}</p>${Object.entries(job.components||{}).map(([key,value])=>`<p>${key==='subscription'?'套餐额度':'额外权益'}：${esc(labels[value.state]||value.state)}${value.reason?' · '+esc(extraReason(value.reason)):''}</p>`).join('')}<p class="hint">刷新不代表额度重置或用卡成功。</p></section>`;}
