function renderExtraBatch(view){if(!extraCurrent(view))return;const d=view.data;if(!d){$('#extra-content').innerHTML=`<p class="notice warn">${esc(view.error||'正在读取…')}</p>${button('extra-batch-reload','重新读取','secondary')}`;return;}const statuses={pending:'待执行',applied:'已应用',unchanged:'未变化',skipped:'已跳过',failed:'失败'},stateLabel=d.execution_failed?'后台执行失败':({preview:'待确认',queued:'后台执行中',completed:'已结束'})[d.status]||d.status;$('#extra-content').innerHTML=`<p>状态：<strong>${esc(stateLabel)}</strong> · 预览有效至 ${beijingDate(d.expires)}</p><p class="hint">固定目标与版本，不重新扩大范围。${d.kind==='policy'?'全局许可将设为'+(d.operation.enabled?'开启':'关闭'):'选定账号将设为'+(d.operation.mode==='deny'?'禁止额外消耗':'继承全局')}。受理成功不等于执行完成。</p>${view.previewSummary?`<p>固定预览：${['before','after'].map(key=>{const c=view.previewSummary[key];return (key==='before'?'变更前':'预计变更后')+' 条件具备 '+fmt(c.allowed)+'／禁止 '+fmt(c.blocked)+'／待配置或核验 '+fmt(c.pending)+'，影响会话 '+fmt(c.sessions);}).join(' → ')}</p>`:''}<p>${Object.entries(d.counts).map(([status,count])=>esc(statuses[status]||status)+' '+fmt(count)).join(' · ')}</p>${view.error?`<p class="notice warn">${esc(view.error)}；保留上次快照，重新读取成功前不能执行。</p>`:''}${d.execution_failed?'<p class="notice warn">后台任务已停止，未完成项不会继续执行。可重新预览未成功项，核对后再次确认。</p>':''}<div class="table-wrap"><table><thead><tr><th>账号</th><th>变更前</th><th>变更后／计划</th><th>结果</th></tr></thead><tbody>${d.items.map(row=>`<tr><td>${esc(row.account_name)}</td><td>${row.before_state.mode==='deny'?'禁止':'继承全局'}${extraBudgetMarkup(row.before_state.budget)}</td><td>${row.desired_configuration.mode==='deny'?'禁止':'继承全局'}${extraBudgetMarkup(row.desired_configuration.budget)}</td><td>${esc(statuses[row.status]||row.status)}<small>${esc(extraReason(row.reason))}</small></td></tr>`).join('')}</tbody></table></div><div class="pager">${button('extra-batch-prev','上一页','secondary','',view.cursors.length<=1||view.loading)}${button('extra-batch-next','下一页','secondary','',!d.has_more||view.loading)}${pageSizeControl('extra-batch',dialogPageSize('extra-batch'))}</div><div class="dialog-actions">${button('extra-batch-reload','重新读取','secondary','',view.busy)}${d.status==='preview'?button('extra-batch-execute',d.kind==='policy'?'确认应用全局许可':'确认执行固定目标','primary','',view.busy||!!view.error||d.expires<=Date.now()):''}${d.kind==='accounts'&&(d.execution_failed||d.status==='completed')?button('extra-batch-retry','重新预览未成功项','secondary','',view.busy||!!view.error):''}${button('extra-global','返回许可管理','secondary')}</div>`;}
async function loadExtraHistory(view,more=false){if(!extraCurrent(view)||view.loading)return;view.loading=true;try{const data=await api('/api/admin/extra-usage/batches?'+new URLSearchParams({limit:'20',...(more&&view.data?.before?{before:view.data.before}:{})}),'GET',undefined,'',view.controller.signal);if(!extraCurrent(view))return;view.data={...data,rows:more?[...view.data.rows,...data.rows]:data.rows};$('#extra-content').innerHTML='<p class="hint">近7天记录</p>'+view.data.rows.map(row=>`<article class="extra-record"><p>${beijingDate(row.created)} · ${row.kind==='policy'?'全局许可':'账号配置'} · ${fmt(row.accounts)} 个账号 · ${esc(row.execution_failed?'后台失败':row.status)}</p>${button('extra-batch-open','查看固定预览／结果','secondary',row.id)}</article>`).join('')+button('extra-history-more','加载更早记录','secondary','',!data.has_more)+button('extra-global','返回许可管理','secondary');}catch(error){if(extraCurrent(view))toast(error.message);}finally{view.loading=false;}}
async function handleExtraAction(action,id){if(!extraEnabled())return;if(action==='extra-account'){const account=state.accounts.find(a=>a.id===id),view=openExtraView('account',(account?.name||'账号')+' · 额外额度与重置卡',id);return loadExtraAccount(view);}if(action==='extra-global'){const view=openExtraView('global','额外额度许可与覆盖情况');Object.assign(view,{selection:new Set(),page:1,q:'',status:''});return loadExtraCoverage(view);}if(action==='extra-batch-open')return openExtraBatch(id);if(action==='extra-history'){const view=openExtraView('history','近7天额外额度配置记录');return loadExtraHistory(view);}const view=extraView;if(!extraCurrent(view)||view.busy||view.loading)return;if(action==='extra-account-reload'){view.loading=true;for(const el of document.querySelectorAll('#extra-content form button'))el.disabled=true;try{await refresh(false);}finally{view.loading=false;}return loadExtraAccount(view);}if(action==='extra-history-more'&&view.data?.has_more)return loadExtraHistory(view,true);if(action==='extra-records-more'&&view.records.has_more){view.busy=true;try{const next=await api(extraEndpoint(view,'/records?limit=20&before='+encodeURIComponent(view.records.before)),'GET',undefined,'',view.controller.signal);if(extraCurrent(view)){view.records={...next,items:[...view.records.items,...next.items]};$('#extra-records').innerHTML=extraRecordsMarkup(view.records);const button=document.querySelector('[data-action=extra-records-more]');if(button)button.disabled=!next.has_more;}}finally{view.busy=false;}return;}if(action==='extra-refresh-retry'){view.jobError='';return pollExtraRefresh(view);}if(action==='extra-refresh'){view.jobError='';view.busy=true;try{view.job=await api(extraEndpoint(view,'/refresh'),'POST',{},'',view.controller.signal);if(extraCurrent(view)){view.busy=false;const target=$('#extra-job-status');if(target)target.innerHTML=extraJobMarkup(view.job);const refreshButton=document.querySelector('[data-action=extra-refresh]');if(refreshButton)refreshButton.disabled=true;}}finally{view.busy=false;}return;}if(action==='extra-policy-preview')return createExtraPreview(view,'policy',{enabled:!view.coverage.policy.enabled,expected_version:view.coverage.policy.version});if(action==='extra-select-page'){for(const row of view.coverage.rows)if(row.reason!=='extra_not_applicable')view.selection.add(row.account_id);return renderExtraCoverage(view);}if(action==='extra-clear-selection'){view.selection.clear();return renderExtraCoverage(view);}if(action==='extra-coverage-page'){view.page=Number(id);return loadExtraCoverage(view);}if(action==='extra-batch-reload')return loadExtraBatch(view);if(action==='extra-batch-next'&&view.data.has_more){view.cursors.push(view.data.after);view.after=view.data.after;return loadExtraBatch(view);}if(action==='extra-batch-prev'&&view.cursors.length>1){view.cursors.pop();view.after=view.cursors.at(-1);return loadExtraBatch(view);}if(action==='extra-batch-execute'||action==='extra-batch-retry'){if(view.error||action==='extra-batch-execute'&&(view.data.status!=='preview'||view.data.expires<=Date.now()))return;view.busy=true;renderExtraBatch(view);try{const retry=action==='extra-batch-retry',policy=view.data.kind==='policy',data=await api(policy?'/api/admin/extra-usage/policy':'/api/admin/extra-usage/batches/'+encodeURIComponent(view.id)+(retry?'/retry':'/execute'),policy?'PATCH':'POST',policy?{preview_id:view.id}:{},'',view.controller.signal);if(!extraCurrent(view))return;if(retry)return openExtraBatch(data.id);await loadExtraBatch(view);void loadExtraPool();}catch(error){if(extraCurrent(view)){view.error=error.message;renderExtraBatch(view);}}finally{view.busy=false;if(extraCurrent(view))renderExtraBatch(view);}}}

async function api(path,method='GET',data,credential='',signal){
  const epoch=authEpoch;
  const r=await fetch(path,{method,signal,headers:{...(credential?{Authorization:'Bearer '+credential}:{}),...(data!==undefined?{'Content-Type':'application/json'}:{})},...(data!==undefined?{body:JSON.stringify(data)}:{})});
  if(r.status===401&&path.startsWith('/api/admin/')&&epoch===authEpoch){admin=false;authEpoch++;state=null;showLogin();}
  let b;try{b=await r.json();}catch{throw Object.assign(Error(r.ok?'服务返回了空或无效响应，请刷新页面后重试':'请求失败（HTTP '+r.status+'），请稍后重试'),{status:r.status});}
  if(!r.ok){const error=Error(b?.error?.message||'请求失败（HTTP '+r.status+'）');error.status=r.status;throw error;}
  if(!b||typeof b!=='object')throw Error('服务返回了无效响应，请刷新页面后重试');
  if(path.startsWith('/api/admin/')&&epoch!==authEpoch)throw Error('登录状态已变更，请重新操作');
  return b;
}
