 const anchor=menu.getBoundingClientRect();options.style.left=Math.max(12,Math.min(anchor.left,window.innerWidth-options.offsetWidth-12))+'px';options.style.top=Math.max(12,Math.min(anchor.bottom+8,window.innerHeight-options.offsetHeight-12))+'px';
