async function loadRequests(automaticScope='',{preservePage=false}={}){
  if(!admin||tab!=='requests'||recordView!=='requests')return;
  requestsRenderPending=false;
  if(!preservePage){requestGroupPages={model:1,member_name:1};requestsFilters.page=1;requestsPageSnapshot='';requestsCursors=new Map([[1,'']]);}
  requestsAbort?.abort();requestsAbort=new AbortController();const signal=requestsAbort.signal;
  const epoch=authEpoch,version=++requestsVersion,filters={...requestsFilters};if(!automaticScope){requestsLoading=true;if(!requestsData)render();else regionBusy('requests-results',true);}
  const current=()=>admin&&epoch===authEpoch&&version===requestsVersion&&tab==='requests'&&recordView==='requests'&&!signal.aborted;
  const query=new URLSearchParams({page:String(filters.page),page_size:String(filters.pageSize),view:'list'});
  for(const field of ['member','model','status','device','type','outcome','from','to','member_missing','model_missing'])if(filters[field])query.set(field,filters[field]);
  if(requestsPageSnapshot)query.set('snapshot',requestsPageSnapshot);
  if(requestsCursors.get(filters.page))query.set('cursor',requestsCursors.get(filters.page));
  try{
    if(requestStatisticsTab!=='list'){
      const summaryQuery=new URLSearchParams(query);summaryQuery.set('view','summary');summaryQuery.delete('cursor');
      const stats=await api('/api/admin/requests?'+summaryQuery,'GET',undefined,'',signal);
      if(!current()||automaticScope&&automaticRefreshScope()!==automaticScope)return;
      if(!stats.summary)throw Error('请求统计响应无效');
      if(stats.snapshot)requestsPageSnapshot=stats.snapshot;
      requestsData={...stats,listLoaded:false,rows:[],pagination:{page:1,pageSize:filters.pageSize,total:stats.summary.requests,totalPages:Math.max(1,Math.ceil(stats.summary.requests/filters.pageSize))},statisticsAt:stats.observedAt,statisticsWatermark:stats.watermark,statisticsWatermarkKind:stats.watermarkKind};requestsLoading=false;connectionState('服务在线');render();return;
    }
    if(state?.capabilities?.requestPageSummary)query.set('view','all');
    let data;
    try{data=await api('/api/admin/requests?'+query,'GET',undefined,'',signal);}
    catch(error){
      if(query.get('view')!=='all'||error.status<500||error.status>599||!Number.isInteger(error.status)||!current())throw error;
      // Preserve the independent list path when a combined server query fails.
      query.set('view','list');data=await api('/api/admin/requests?'+query,'GET',undefined,'',signal);
    }
    if(!current())return;
    if(automaticScope&&automaticRefreshScope()!==automaticScope)return;
    connectionState('服务在线');
    if(data.snapshot)requestsPageSnapshot=data.snapshot;
    if(data.pagination.nextCursor)requestsCursors.set(data.pagination.page+1,data.pagination.nextCursor);
    if(data.summary)Object.assign(data,{statisticsAt:data.observedAt,statisticsWatermark:data.watermark,statisticsWatermarkKind:data.watermarkKind});
    data.models??=requestsData?.models||[];data.members??=requestsData?.members||[];
    const changed=requestsSnapshot(data)!==requestsSnapshot(requestsData);requestsData=data;requestsFilters.page=data.pagination.page;requestsLoading=false;if(!automaticScope||changed||data.summary?.active>0)render();
    if(!data.summary){
      const summaryQuery=new URLSearchParams(query);summaryQuery.set('view','summary');summaryQuery.delete('cursor');if(data.snapshot)summaryQuery.set('snapshot',data.snapshot);
      void api('/api/admin/requests?'+summaryQuery,'GET',undefined,'',signal).then(stats=>{
        if(!current()||requestsData!==data)return;
        Object.assign(data,{summary:stats.summary,byModel:stats.byModel,byMember:stats.byMember,models:stats.models,members:stats.members,statisticsAt:stats.observedAt,statisticsWatermark:stats.watermark,statisticsWatermarkKind:stats.watermarkKind});renderRequestStatistics();
      }).catch(e=>{if(!current()||requestsData!==data)return;data.statisticsError=e.message;renderRequestStatistics();});
    }
  }catch(e){if(!current())return;if(automaticScope){if(automaticRefreshScope()===automaticScope)connectionState('连接异常',true);return;}requestsLoading=false;requestsData=null;render();toast(e.message);}finally{if(current())regionBusy('requests-results',false);}
}
function requestFilterFields(){const outcome=state?.capabilities?.typeStatistics?'outcome':'status';return requestStatisticsTab==='model'?['model',outcome]:requestStatisticsTab==='member_name'?['member',...(state?.capabilities?.typeStatistics?['type']:[]),outcome]:['member','model',...(state?.capabilities?.typeStatistics?['type']:[]),outcome,...(state?.capabilities?.deviceAccess?['device']:[])];}
function requestsSection(){
  const data=requestsData,f=requestsFilters,semantic=!!state?.capabilities?.typeStatistics,visible=new Set(requestFilterFields());
  const select=(field,label,rows)=>`<label>${label}<select id="requests-${field}" aria-label="${label}"><option value="">全部</option>${rows.map(([value,text])=>`<option value="${esc(value)}" ${f[field]===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
  const filters=requestsTypeScopeSummary()+`<div class="page-toolbar request-controls"><div class="filter-grid history-filters request-filters">${visible.has('device')?`<label>设备<select id="requests-device"><option value="">全部设备</option><option value="unknown" ${f.device==='unknown'?'selected':''}>未记录设备</option>${f.device&&f.device!=='unknown'?`<option value="${esc(f.device)}" selected>已选设备 ${esc(f.device.slice(-8))}</option>`:''}</select></label>`:''}${visible.has('type')?`<label>请求发生时类型<select id="requests-type">${typeOptions(f.type)}</select></label>`:''}${visible.has('member')?select('member','用户',(data?.members||[]).map(x=>[x.id,x.name+(x.removed_at?'（已移除）':'')])):''}${visible.has('model')?select('model','模型',(data?.models||[]).map(x=>[x,x])):''}${semantic?select('outcome','业务结果',Object.entries(businessOutcomeLabels)):select('status','状态',['running','queued','ok','failed','unknown','interrupted','cancelled','rejected','reconciled'].map(x=>[x,phaseLabels[x]||({running:'执行中',reconciled:'已核对'})[x]||x]))}</div>${requestStatisticsTab==='list'&&state?.capabilities?.recordingHistory?`<div class="actions">${button('requests-export-structured','导出当前筛选','secondary')}</div>`:''}</div>`;
  const tabs=`<div class="actions request-statistics-tabs" role="tablist" aria-label="请求统计视图">${[['list','近7天请求明细'],['model','按模型统计'],['member_name','按用户统计']].map(([id,label])=>`<button type="button" role="tab" aria-selected="${requestStatisticsTab===id}" data-action="request-statistics-tab" data-id="${id}" class="${requestStatisticsTab===id?'primary':'secondary'}">${label}</button>`).join('')}</div>`;
  if(requestsLoading&&!data)return panel('请求记录与统计',`<div class="panel-body">${tabs}${filters}</div>`+loadingRegion('',true,'正在读取筛选结果…'));
  if(!data)return panel('请求记录与统计',`<div class="panel-body">${tabs}${filters}</div>${empty('暂无请求数据。')}`,button('requests-reload','重新读取','text-button'));
  const t=data.summary,p=data.pagination;
  const summary=t?`<div class="stats request-stats">${[['请求 / 成功',fmt(t.requests)+' / '+fmt(t.success),'处理中 '+fmt(t.active)],['参考消耗（USD）',referenceTotal(t.standard),referenceCoverage(t.standard)],['未计量 / 缺费率',fmt(t.standard?.unmetered)+' / '+fmt(t.standard?.unpriced),''],['完成平均耗时',(t.average_ms/1000).toFixed(2)+'s','']].map(([label,value,hint])=>`<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${value}</div>${hint?'<small>'+hint+'</small>':''}</div>`).join('')}</div>`:`<p class="hint">${esc(data.statisticsError||'汇总独立加载中，明细可先查看。')}</p>`;
  const grouped=(title,rows,name)=>{const size=requestGroupPageSizes[name],totalPages=Math.max(1,Math.ceil(rows.length/size)),page=Math.min(requestGroupPages[name],totalPages);requestGroupPages[name]=page;return rows.length?`<div class="table-wrap"><table><thead><tr><th>${name==='model'?'模型':'用户'}</th><th>请求 / 成功</th><th>参考合计（USD）</th><th>输入 / 输出（USD）</th><th>未计量 / 缺费率</th></tr></thead><tbody>${rows.slice((page-1)*size,page*size).map(x=>`<tr><td>${esc(x[name]||'未记录')}</td><td>${fmt(x.requests)} / ${fmt(x.success)}</td><td>${referenceTotal(x.standard)}<small>人工核对 ${referenceMoney(x.standard?.adjustment)}</small></td><td>${referenceMoney(x.standard?.input)} / ${referenceMoney(x.standard?.output)}<small>其中缓存 ${referenceMoney(x.standard?.cached)}</small></td><td>${fmt(x.standard?.unmetered)} / ${fmt(x.standard?.unpriced)}</td></tr>`).join('')}</tbody></table></div>`+`<div class="pager">${button('request-group-page','上一页','secondary',name+':'+(page-1),page<=1)}<span>第 ${page} / ${totalPages} 页 · 共 ${fmt(rows.length)} 组</span>${button('request-group-page','下一页','secondary',name+':'+(page+1),page>=totalPages)}${pageSizeControl('request-group:'+name,size)}</div>`:empty('当前筛选无数据。');};
  const hasNext=p.nextCursor===undefined?p.page<p.totalPages:!!p.nextCursor;
  const pager=`<div class="session-pager"><span>${p.cursorMode?'第 '+p.page+' 页 · 当前匹配 '+fmt(p.total)+' 条':'第 '+p.page+' / '+p.totalPages+' 页 · 共 '+fmt(p.total)+' 条'}</span><label>每页<select id="requests-page-size">${PAGE_SIZES.map(n=>`<option value="${n}" ${p.pageSize===n?'selected':''}>${n}</option>`).join('')}</select>条</label><div class="actions">${button('requests-page','上一页','secondary',p.page-1,p.page<=1)}${button('requests-page','下一页','secondary',p.page+1,!hasNext)}</div></div>`;
  const timing=data.statisticsAt?`统计时间 ${beijingDate(data.statisticsAt)}${data.statisticsWatermark!==data.watermark?data.statisticsWatermarkKind==='postgres_visibility'?' · 列表与汇总来自不同读取快照，分组与合计使用同一统计水位':' · 列表加载后数据已有变化，分组与合计使用同一统计水位':''}`:'';

  const content=requestStatisticsTab==='list'?requestTable(data.rows)+pager:t?grouped(requestStatisticsTab==='model'?'按模型统计':'按用户统计',requestStatisticsTab==='model'?data.byModel||[]:data.byMember||[],requestStatisticsTab):`<p class="hint">${esc(data.statisticsError||'正在加载统计…')}</p>`;
  return panel('请求记录与统计',`<div class="panel-body">${tabs}${filters}<p class="hint compact-statistics-note" title="${esc(timing)}">近7天 · 北京时间${data.statisticsAt?' · 更新于 '+beijingDate(data.statisticsAt):''}</p></div>`+loadingRegion(summary+content,requestsLoading,'','requests-results'));
}
