  const pager=p?`<div class="session-pager"><span class="hint">共 ${fmt(p.total)} 条 · 第 ${p.page} / ${p.totalPages} 页${historyLoading?' · 正在读取…':''}</span><div class="actions">${button('history-page','首页','secondary','1',historyLoading||p.page<=1)}${button('history-page','上一页','secondary',p.page-1,historyLoading||p.page<=1)}${button('history-page','下一页','secondary',p.page+1,historyLoading||p.page>=p.totalPages)}${button('history-page','末页','secondary',p.totalPages,historyLoading||p.page>=p.totalPages)}${pageSizeControl('history',historyFilters.pageSize,historyLoading)}</div></div>`:'';
  return panel('系统操作历史',`<div class="panel-body compact-history-filters">${filters}</div>${loadingRegion(table+pager,historyLoading||pageRefreshing(),'正在查询系统操作历史…','history-results')}`);
