async function openNightlyHistory(day,revision){
  modal('<h2>定时批次</h2><p>正在读取…</p>',true);
  const view={history:true,day,id:day,epoch:authEpoch,dialog:dialogVersion,controller:new AbortController(),status:'completed',busy:true,section:'groups',items:[],cursor:0,back:[],hasMore:false,names:new Map()};planningPreview=view;
  try{
    const result=await api('/api/admin/history/nightly/'+day+(revision===undefined?'':'?revision='+revision),'GET',undefined,'',view.controller.signal);if(!currentPlanningPreview(view))return;
    if(result.paginated!==true||result.day!==day||!result.results||!Array.isArray(result.accounts)||!Number.isSafeInteger(result.visibleUntil)||Object.keys(planningSections).some(section=>!Number.isSafeInteger(result.counts?.[section])||result.counts[section]<0))throw Error('批次概要响应无效');
    view.run=result;view.revision=result.revisionAware?result.revision:undefined;view.names=new Map(result.accounts.map(a=>[a.id,a.name]));view.plan={counts:result.counts,window:result.window};view.expires=result.visibleUntil;view.plannedAt=result.plannedAt;
    if(!result.hasPlan)view.error='此批次未保存完整计划，可查看批次状态；没有可确认的迁移明细。';
  }catch(error){if(currentPlanningPreview(view)&&!view.controller.signal.aborted)view.error=error.message;}
  finally{view.busy=false;renderPlanningPreview(view);}
  if(currentPlanningPreview(view)&&view.plan&&view.run.hasPlan){view.expiryTimer=setTimeout(()=>expirePlanningPreview(view),Math.max(0,view.expires-Date.now()));await loadPlanningPage(view);}
}
function heavyHistory(planning){
  if(!planning)return '';
  const session=m=>typeof m==='string'?m:m.client_session_id||m.session_id||'旧记录未保留会话标识';
  return `${planning.prioritySessions?.length?`<p class="hint">已纳入优先迁移的重会话：${planning.prioritySessions.map(m=>esc(session(m))).join('、')}</p>`:''}${planning.heavySkipped?.length?`<div class="notice">${planning.heavySkipped.map(m=>`${esc(session(m))}：${esc(reasonLabels[m.reason]||'历史原因未记录')}`).join('<br>')}</div>`:''}`;
}
function nightlyHistory(r){
  const name=id=>r.accounts.find(a=>a.id===id)?.name||id||'—',session=m=>m.client_session_id||m.session_id||'未记录';
  return `<h2>定时批次 · ${esc(r.day)}</h2>${r.metric?'':'<div class="notice">此批次为旧统计口径，缺少换算依据，隐藏不可比较的历史用量；迁移记录保留。</div>'}<p>开始：${date(r.started)} · 结束：${date(r.ended)} · ${esc(nightlyRunStatus(r))}</p><p>计划迁移 ${r.moves.length} 个，确认已迁移 ${r.moves.filter(m=>m.applied===true).length} 个，跳过 ${r.skipped.length} 项。</p><p class="hint">以下是执行当时保存的计划，表格中的“计划后”不等于全部实际执行。每个会话的执行结果见迁移清单。统计窗口：${date(r.window?.start)} 至 ${date(r.window?.end)}。</p>${r.reason?`<div class="notice warn">${esc(reasonLabels[r.reason]||'批次未完成')}</div>`:''}${r.summaries.map(g=>`${planningHint(g.planning)}${heavyHistory(g.planning)}<div class="table-wrap"><table><thead><tr><th>账号</th><th>计划前负载</th><th>固定负载</th><th>目标负载</th><th>计划后负载</th></tr></thead><tbody>${g.accounts.map(id=>`<tr><td>${esc(name(id))}</td><td>${referenceMoney(g.before[id])}</td><td>${referenceMoney(g.fixedLoad[id])}</td><td>${referenceMoney(g.target[id])}</td><td>${referenceMoney(g.after[id])}</td></tr>`).join('')}</tbody></table></div>`).join('')}<h3>迁移清单</h3>${r.moves.length?`<div class="table-wrap"><table><thead><tr><th>会话 / 员工</th><th>原账号 → 目标账号</th><th>历史负载</th><th>执行结果</th></tr></thead><tbody>${r.moves.map(m=>`<tr><td class="mono">${esc(session(m))}<small>${esc(m.member)}</small></td><td>${esc(name(m.from))} → ${esc(name(m.to))}</td><td>${referenceMoney(m.weight)}</td><td>${m.applied===null?'旧记录未保存结果':m.applied?'已迁移':'未执行'}</td></tr>`).join('')}</tbody></table></div>`:empty('本批次没有计划迁移')}<h3>跳过原因</h3>${r.skipped.length?r.skipped.map(m=>`<div class="mini-row"><span class="mono">${esc(m.session_id?session(m):m.accounts?.length?m.accounts.map(name).join(' / '):m.account?name(m.account):'账号组（旧记录未记录成员）')}</span><span>${esc(reasonLabels[m.reason]||'历史原因未记录')}</span></div>`).join(''):empty('没有跳过项')}<p class="hint">新批次负载为当时Standard参考USD及在途估计，不代表实际扣款或官方订阅额度。</p><div class="dialog-actions">${button('close','关闭','primary')}</div>`;
}
function sessionFiltersBar(){
  if(!state.capabilities?.sessionFilters)return '';const f=sessionsFilters,disabled=sessionsLoading?'disabled':'';
  return `${sessionsLoadError?'<div class="notice warn" role="alert">读取失败，正在显示上次结果。'+button('retry-workspace','重新读取','secondary')+'</div>':''}<form id="session-filter-form" class="filter-grid history-filters"><label>员工 / 会话<input name="q" maxlength="100" value="${esc(f.q)}" placeholder="搜索员工名称或会话标识" ${disabled}></label><label>员工当前类型<select name="type" ${disabled}>${typeOptions(f.type,'全部使用类型',{current:true})}</select></label><label>绑定账号<select name="account" ${disabled}><option value="">全部账号</option>${state.accounts.map(a=>`<option value="${esc(a.id)}" ${f.account===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}${f.account&&!state.accounts.some(a=>a.id===f.account)?`<option value="${esc(f.account)}" selected>已选账号（当前账号池不可用）</option>`:''}</select></label><label>访问状态<select name="status" ${disabled}><option value="">全部状态</option><option value="enabled" ${f.status==='enabled'?'selected':''}>允许访问</option><option value="disabled" ${f.status==='disabled'?'selected':''}>禁止访问</option></select></label><div class="filter-actions filter-grid-actions"><button class="primary" ${disabled}>查询</button>${button('sessions-filter-reset','清空筛选','secondary','',sessionsLoading)}</div></form>`;
}
function sessionPager(){
  const p=state.sessionsPagination||{page:sessionsPage,pageSize:sessionsPageSize,total:state.sessions.length,totalPages:1};
  const control=(label,page,disabled)=>`<button type="button" class="secondary" data-action="sessions-page" data-id="${page}" ${disabled||sessionsLoading?'disabled':''}>${label}</button>`;
  return `<div class="session-pager" aria-label="会话分页"><span class="hint">共 ${fmt(p.total)} 个会话 · 第 ${fmt(p.page)} / ${fmt(p.totalPages)} 页${sessionsLoading?' · 正在读取…':''}</span><div class="actions"><label>每页<select id="session-page-size" aria-label="每页会话数" ${sessionsLoading?'disabled':''}>${PAGE_SIZES.map(n=>`<option value="${n}" ${n===p.pageSize?'selected':''}>${n} 条</option>`).join('')}</select></label>${control('首页',1,p.page<=1)}${control('上一页',p.page-1,p.page<=1)}${control('下一页',p.page+1,p.page>=p.totalPages)}${control('末页',p.totalPages,p.page>=p.totalPages)}</div></div>`;
}
function render(){
  $('.page')?.classList.toggle('overview-page',admin&&tab==='overview');
  if(tab!=='accounts')stopExtraPool();
  if(!admin&&tab!=='playground'){showLogin();return;}
  showShell();document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===navigationTab()));const crumb=$('#crumb');if(crumb)crumb.textContent=labels[tab];
  const showGuide=tab==='playground'&&admin&&connectionView==='guide';
  if(!state&&(tab!=='playground'||showGuide)){$('#content').innerHTML=initialLoadError?`<section class="initial-state-error" role="alert"><p>工作空间读取失败</p><p class="hint">${esc(initialLoadError)}</p>${button('retry-workspace','重新读取','primary')}</section>`:loadingRegion('',true,'正在读取工作空间…','initial-state-results');return;}
  if(stateNeedsPageData()&&!(tab==='sessions'&&sessionsConfirmedSnapshot)){$('#content').innerHTML=loadingRegion(button('retry-workspace','重新读取','secondary'),pageRefreshing(),'正在读取页面数据…','state-page-results');return;}
  let html='';
  if(tab==='overview'){
    const total=state.totals,active=state.accounts.filter(a=>a.enabled&&a.state==='ready').length;
    const stats=[['近7天请求总数',fmt(total.requests),`成功 ${fmt(total.success)} 次`],['处理中 / 排队',`${fmt(state.busy)} / ${fmt(state.queue)}`,''],['可用账号（全公司）',`${active} <span class="muted">/ ${state.accounts.length}</span>`,''],['员工（全公司）',fmt(state.memberCount??state.members.length),'']];
    const days=Array.from({length:7},(_,i)=>{const d=new Date((state.usageWindow?.start??Date.now()-6*86400000)+i*86400000),day=d.toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});const drow=state.daily.find(x=>x.day===day);return {day,requests:Number(drow?.requests??0)};});
    html=`<div class="page-toolbar overview-controls">${state.capabilities?.typeStatistics?`<div class="filter-grid overview-filters"><select id="overview-type" aria-label="使用类型">${typeOptions(overviewType,'全公司全部类型')}</select></div>`:''}</div><div class="stats">${(overviewType?stats.slice(2):stats).map(([label,value,hint])=>`<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${value}</div>${hint?'<small>'+hint+'</small>':''}</div>`).join('')}</div>`;
    if(!overviewType)html+=`<div class="two-col">${panel('最近 7 天请求',`<div class="panel-body"><div class="chart">${days.map(d=>`<div class="bar-col"><span class="chart-label">${fmt(d.requests)}</span><div class="bar" data-height="${d.requests/Math.max(1,...days.map(x=>x.requests))*100}"></div><small>${d.day.slice(5).replace('-','/')}</small></div>`).join('')}</div></div>`,'<span class="hint">北京时间 · 请求数</span>')}${panel('上游连接',`<div class="panel-body">${state.accounts.length?state.accounts.map(a=>`<div class="mini-row"><div><strong>${esc(a.name)}</strong><small class="muted"> · ${esc(apiAccount(a)?'OpenAI API Key':a.kind==='claude'?'Claude订阅':'Codex订阅')}</small></div>${a.enabled?badge(a.state):badge('offline')}</div>`).join(''):empty('尚未添加账号')}</div>`,button('go-accounts','管理 →','text-button'))}</div>`;
    if(overviewType)html+=overviewStatisticsSection();
  }
  if(tab==='members')html=pagedPeople()?pagedMembersSection():heading('PEOPLE & ACCESS','员工与密钥','',memberManagementActions())+panel('员工列表',memberTable(state.members),`<span class="hint">${state.members.length} 位员工</span>`);
  if(tab==='accounts'&&state.capabilities?.accountPackages)html=packagePoolSection();
  if(tab==='accounts'&&!state.capabilities?.accountPackages)html=heading('UPSTREAM POOL','上游账号池','',accountPoolActions())+panel('账户列表',loadingRegion(packagePoolTable(),pageRefreshing(),'正在读取账号状态…','account-pool-results'));
  if(tab==='sessions'&&sessionSnapshotExpired())html=heading('USAGE DATA','使用数据','')+recordTabs()+panel('近7天活动会话',loadingRegion('<p class="hint">统计窗口已更新，请重新读取会话。</p>'+button('retry-workspace','重新读取','secondary'),pageRefreshing(),'正在读取会话…','state-page-results'));
  else if(tab==='sessions')html=heading('USAGE DATA','使用数据','')+recordTabs()+sessionFiltersBar()+panel('近7天活动会话',loadingRegion((state.sessions.length?`<div class="table-wrap"><table><thead><tr><th>Codex Session / 员工</th><th>绑定账号</th><th>近7天请求数</th><th>最近活动</th><th>操作</th></tr></thead><tbody>${state.sessions.map(s=>`<tr><td class="mono">${esc(sessionDisplayId(s))}<small>${esc(s.member_name)}</small></td><td>${esc(s.account_name)}</td><td>${fmt(s.request_count)}</td><td>${date(s.updated)}</td><td>${button('session-actions','管理会话','table-button',s.id,sessionsLoading||!!sessionsLoadError)}</td></tr>`).join('')}</tbody></table></div>`:empty(state.capabilities?.sessionFilters&&Object.values(sessionsFilters).some(Boolean)?'没有符合筛选条件的会话。':'发送第一条请求后自动创建会话。'))+sessionPager(),sessionsLoading||pageRefreshing(),'正在读取会话…','sessions-results'));
  if(tab==='requests'){
    const rows=pagedPeople()?usageRows():usageRows().filter(k=>!requestFilter||k.member_name.includes(requestFilter)||(k.full_key||k.prefix).includes(requestFilter));
    html=heading('USAGE DATA','使用数据','')+recordTabs(recordView==='usage'?`<input id="request-filter" placeholder="搜索员工或 Key" value="${esc(requestFilter)}" aria-label="搜索员工或 Key">`:'');
    if(recordView==='usage')html+=panel(recentUsageTitle(),loadingRegion(usageTable(rows)+(pagedPeople()?keyUsagePager():''),keyUsageLoading||!pagedPeople()&&pageRefreshing(),'正在读取用量…','key-usage-results'));
    if(recordView==='requests')html+=requestsSection();
    if(recordView==='types')html+=typeStatisticsSection();
    if(recordView==='recordings')html+=recordingAdminSection();
  }
  if(tab==='history')html=heading('SYSTEM MANAGEMENT','系统管理','')+connectionTabs()+historySection();
  if(tab==='playground'&&!showGuide){
    html=heading('SYSTEM MANAGEMENT',admin?'系统管理':'接入与测试','')+(admin?connectionTabs():'')+`<div class="chat-layout"><section class="panel"><div class="chat-controls"><h2>连接设置</h2><label>员工 API Key<input id="test-key" type="password" autocomplete="off" placeholder="hg_…" value="${esc(testKey)}" ${sending?'disabled':''}></label><button class="secondary" id="check-key">查看近7天用量</button><div id="my-quota" class="details-line"></div><label>模型<select id="chat-model" ${sending?'disabled':''}><option value="codex" ${chatModel==='codex'?'selected':''}>Codex</option><option value="claude" ${chatModel==='claude'?'selected':''}>Claude</option>${[...new Set([...platformModels,...(state?.accounts||[]).filter(a=>a.auth_mode==='platform'&&a.enabled&&a.state==='ready').flatMap(a=>JSON.parse(a.platform_models||'[]').map(m=>a.kind+'/'+m))])].map(m=>`<option value="${esc(m)}" ${chatModel===m?'selected':''}>${esc(platformModelLabel(m))}</option>`).join('')}</select></label><div class="notice">仅测试文本对话，不执行代码或访问工作文件。</div>${button('clear-chat','＋ 新建会话','text-button')}<p class="hint mono">${chatSession?esc(chatSession):'尚未创建会话'}</p><p class="hint">${chatModel.includes('/')?'刷新页面会清空聊天记录，无法恢复。':'刷新页面会清空显示；保留 session_id 可继续上下文。'}</p></div></section><section class="panel"><div class="panel-heading"><h2>对话测试</h2><span class="hint">${chatSession?'会话已绑定':'新会话'}</span></div><div class="chat-log" id="chat-log">${renderChat()}</div><form class="composer" id="chat-form"><textarea id="prompt" placeholder="输入测试问题" aria-label="消息" required ${sending?'disabled':''}>${esc(draft)}</textarea><div class="composer-bottom"><span class="hint">${sending?'正在等待回复，最长约 2 分钟…':'每次请求会消耗真实订阅额度'}</span><button class="primary" ${sending?'disabled':''}>${sending?'处理中…':'发送请求 ↗'}</button></div></form></section></div>`;
  }
  if(showGuide)html=heading('SYSTEM MANAGEMENT','系统管理','')+connectionTabs();
  if(showGuide)html+=`<details class="guide-notice"><summary>使用前告知：平台可能记录设备及对话信息</summary>${accessDataNotice()}</details>`+panel('Codex Windows / WSL 接入',codexGuide(state.endpoint));
  if(showGuide)html+=panel('image2 图片生成与编辑（测试接入）',imageGuide(state.endpoint));
  $('#content').innerHTML=html;syncLoadingRegions();document.querySelectorAll('[data-height]').forEach(el=>el.style.height=el.dataset.height+'px');document.querySelectorAll('[data-width]').forEach(el=>el.style.width=el.dataset.width+'%');
  bindHistoryForm();bindRequestFilters();bindTypeStatistics();bindRecordingAdmin();bindPackagePool();
  if(tab==='playground'&&!showGuide){$('#chat-form').onsubmit=sendChat;$('#check-key').onclick=checkKey;$('#test-key').oninput=e=>{testKey=e.target.value;$('#my-quota').textContent='';};$('#prompt').oninput=e=>draft=e.target.value;$('#chat-model').onchange=e=>{if(sending)return;chatModel=e.target.value;chat=[];chatSession='';chatOwner='';render();};$('#chat-log').scrollTop=$('#chat-log').scrollHeight;}
  if(tab==='sessions'&&!sessionSnapshotExpired()&&state.capabilities?.sessionFilters)$('#session-filter-form').onsubmit=async event=>{event.preventDefault();if(sessionsLoading)return;const form=new FormData(event.target);sessionsFilters=Object.fromEntries(['q','type','account','status'].map(key=>[key,String(form.get(key)||'').trim()]));sessionsPage=1;sessionsLoading=true;render();await refresh();};
  if(tab==='sessions'&&!sessionSnapshotExpired()){$('#session-page-size').onchange=async e=>{if(sessionsLoading)return;sessionsPageSize=Number(e.target.value);sessionsPage=1;sessionsLoading=true;render();await refresh();};}
  if(tab==='requests'&&recordView==='usage'){$('#request-filter').onchange=e=>{requestFilter=e.target.value;if(pagedPeople()){keyUsagePage=1;void loadKeyUsage();}else render();};}
  if(tab==='members'&&pagedPeople())bindMemberFilters();
}
function accessDataNotice(){return `<div class="panel-body"><p>使用 Harbor 时，平台可能记录以下信息，供公司授权管理员进行使用管理、审计和故障排查：</p><ul><li>身份与请求信息：员工与 Key 标识、时间、来源 IP、客户端信息、模型、状态、耗时、用量和参考消耗。</li><li>设备信息：启用设备登记或认证时，可记录设备名称、系统／客户端信息、安装标识、设备指纹及认证状态；普通兼容接入未必能取得这些信息。</li><li>对话与工作记录：开启正文及上下文采集时，可记录用户消息、模型回复、工具调用及返回（包括命令、补丁和工具结果中携带的文本、代码和文件片段）、公开推理摘要，以及请求中实际包含的历史消息、指令和工具定义。</li><li>附件信息：可能记录附件名称、类型、大小、摘要或引用等元信息；不保存原始附件二进制、隐藏推理或不透明的加密推理。</li></ul><p>实际记录范围受平台配置、客户端和上游返回内容限制，不代表能够获取设备上的全部文件或完整操作。平台对采集副本进行脱敏和加密，但无法保证所有敏感内容均被识别；请勿提交未获授权的密码、个人信息或公司资料。请求仍会发送至对应的上游 AI 服务。</p><p>正文按管理员设置的保留期保存，也可设置无限期；页面查询范围不等于数据保存期限，更早数据可能仍在数据库中。具体用途、访问权限、保存期限及删除要求，请向公司管理员确认。本文档不包含实际访问 Key，请通过公司指定渠道单独领取。</p></div>`;}
function codexGuide(endpoint){return `<div class="panel-body"><p>Windows：%USERPROFILE%&#92;.codex&#92;config.toml；WSL：~/.codex/config.toml。合并以下配置，顶层键放在第一个表头之前，不覆盖已有配置。</p><pre class="code">model = "gpt-6.1-sol"
model_provider = "harbor"
web_search = "disabled"

[model_providers.harbor]
name = "Harbor"
base_url = ${esc(JSON.stringify(endpoint))}
wire_api = "responses"
env_key = "HARBOR_API_KEY"
requires_openai_auth = false
supports_websockets = false

[features]
memories = false

[memories]
generate_memories = false
use_memories = false</pre><p>将员工 Key 放入客户端进程的 HARBOR_API_KEY 环境变量，然后完全退出并重启客户端。Windows 桌面应用必须能读取该变量；WSL需单独设置。不要把Key写进TOML或工程。</p><p>默认使用 gpt-6.1-sol，可在 Codex 中切换；模型名使用 GET /v1/models 返回的实际名称，推理强度按客户端选择转发。为让模型选择器显示最新模型，请带员工Key从 /v1/codex/models 下载目录，设置顶层 model_catalog_json 为文件的绝对路径并重启客户端；模型或Key权限更新后重新下载。管理员在“员工与密钥→员工详情→模型权限”按Key限制；目录只返回允许项，顶层model也需设为允许模型。客户端内置/旧缓存可能仍显示其他选项，但服务端会在转发前拒绝。</p><p>文件读写和命令在客户端执行，网关只转发请求。同一 Key、同一账号支持多会话并行；中断后可继续原任务。</p></div>`;}
function accessGuideDocument(endpoint){
 const target=new URL(endpoint);if(!['http:','https:'].includes(target.protocol)||target.username||target.password||target.search||target.hash)throw Error('接入地址无效，请联系管理员');
 return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'"><title>Harbor 接入说明</title><style>body{font-family:system-ui,'Microsoft YaHei',sans-serif;max-width:960px;margin:32px auto;padding:0 24px;color:#22352f;line-height:1.75}h1{font-size:26px}h2{font-size:20px;margin-top:32px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f6f4;padding:16px;border-radius:8px}li{margin:8px 0}label{display:block;font-weight:600}</style></head><body><h1>Harbor 接入说明</h1><h2>使用前告知</h2>${accessDataNotice()}<h2>Codex Windows / WSL 接入</h2>${codexGuide(target.href.replace(/\/$/,''))}<h2>image2 图片生成与编辑（测试接入）</h2>${imageGuide(target.href.replace(/\/$/,''))}</body></html>`;
}
function platformGuideDocument(endpoint){
 const sections=`<h2>用量统计口径</h2><p>参考消耗以USD展示：分别按模型官方Standard短上下文参考价计算非缓存输入、缓存读取和输出，再汇总。缓存读取已包含在输入Token总数中，计算非缓存输入时先扣除缓存，避免重复计价。人工核对金额单列，不伪造缺失的原始计量。</p><p>这是统一比较资源使用的参考值，不是官方账单、订阅实际扣额或赠额抵扣证明；不包含Fast、长上下文等附加费及工具、存储费用。金额保留两位小数，小额可能显示0.00；汇总使用未舍入数值，因此明细显示值相加可能与合计略有差异。费率配置保留原精度。</p><p>近7天指北京时间今天及前6天，近12小时为滚动窗口。请求按完成时间归属，进行中的请求暂按开始时间。缺计量和缺费率分别标记，不当作零；更早记录留在数据库，页面不提供历史入口。已经计价的请求固定所用费率版本，后续费率同步不改写旧结果。未经过Harbor的调用不在统计中。</p>
 <h2>员工、Key与模型权限</h2><p>员工可持有多个Key，各Key的启停、有效期和允许模型独立管理；员工停用会禁止其全部Key访问，但保留各Key自身状态。Key模型范围为“无限制”时不限制模型，空允许列表则没有可用模型，二者不能混同。模型还须得到实际上游账号支持。</p><p>模型目录按Key权限过滤，服务端在请求转发前再次校验。Codex选择器可能保留本地内置或旧缓存；按接入说明加载过滤后的目录并重启客户端，权限改变后需重新下载。客户端仍显示的其他模型并不代表获得调用权限。</p><p>复制员工Key时会附带当前可用模型和共享限额。配置客户端时，Key字段只填写第一行的Key本身，不粘贴后面的说明。接入文档不包含任何实际Key或上游账号凭据。</p>
 <h2>模型共享限额</h2><p>管理员按具体模型配置参考USD上限，窗口为滚动24小时或滚动7天，同一员工全部Key共享，不在凌晨清零。达到上限后拒绝后续新请求；已经派发的请求继续完成并结算，最终用量可能超过上限。未开启限额或未配置该模型规则表示该模型没有本地用量上限，仍须通过模型权限及上游检查。</p><p>使用类型为员工提供默认模型与共享限额；保存类型默认规则不会自动覆盖现有员工。应用到现有员工须预览固定目标，保留明确的个人例外，并检查版本变化。更改类型标签和应用默认配置是不同操作。</p>
 <h2>订阅账号、API Key与分配</h2><p>Codex订阅日常只填写美元月费，月费是档位标注，不能按价格直接推测Token容量、剩余量或额度倍率；额度以官方提供的快照为准。已有可信容量配置和调度策略保留，编辑月费不会改动它们。官方未提供的余额、重置卡数量或设备属性保持未知，不填零代替。</p><p>官方API Key独立加密保存，开关和人工分配占比长期由管理员控制，不随凌晨恢复。占比为0时不参与普通新会话分配，人工固定会话仍按其绑定使用；真实费用和可抵扣的赠额以官方账单为准。</p><p>自动分配结合当前策略、官方额度及重置时间；人工临时权重和订阅会话临时固定的期限以服务器保存的到期时间为准。定时转移按当前配置的北京时间时点执行，预览不会立即修改绑定。转移以模型请求为边界，已派发请求继续使用原账号；失败请求不自动重放。重会话优先、偏差方向和最少迁移的实际计划及受限原因可在执行记录中核对。</p>
 <h2>账号启停与额外额度</h2><p>停用账号会尝试迁移其绑定会话，并持续停用直至管理员手动启用；当前请求继续完成。无可用接收账号时整笔停用操作拒绝。临时权重为0与停用不同，应以页面实际权重及到期时间为准。订阅额外额度是否可使用、适用模型和实际扣费由官方账号权益及服务端检查共同决定，正权重不能保证官方一定接受请求。</p>
 <h2>请求、正文与设备信息</h2><p>请求记录区分业务结果、计量状态和内容完整性。业务成功不代表工具过程和正文全部采集成功；正文可能受关闭采集、上游缺失、存储错误、超限或保留期影响。可记录网关收到的公开文本、工具调用及结果、上下文和附件元信息，隐藏推理、原始附件二进制及临时凭据不进入普通正文。完整采集范围及使用前告知见本文开篇。</p><p>普通接入可自动获得请求的来源IP和客户端上报信息，但不能仅靠IP或User-Agent证明物理设备身份，也不能凭普通HTTP读取硬件指纹。设备证明仅在客户端提供并通过服务端验证时有效；不自动登记或批准设备，不把未认证接入伪装为已认证。删除页面中的设备管理入口不改变已有服务端认证要求。</p><p>正文默认不加载，管理员主动查询后才读取。正文保留期可选无限期；已有请求元数据和用量不会因更换或删除Key而清空。设置较短正文保留期可能使正文及相关导出提前到期，具体影响须以执行前预览为准。</p>
 <h2>系统操作与状态</h2><p>系统操作历史记录账号、员工、Key、权限、限额、权重及转移等管理动作；与模型使用记录分别查看。批量操作和导出是后台任务，已受理不等于已完成，关闭弹窗不取消已经受理的任务。最近执行时间、状态、失败原因和实际计划保留在对应页面。</p><p>本文说明平台当前口径，不包含实时账号、员工、Key、对话或余额数据；实际配置及结果以服务端保存的状态为准。</p>`;
 return accessGuideDocument(endpoint).replaceAll('Harbor 接入说明','Harbor 平台说明').replace('</body>',sections+'</body>');
}
function downloadPlatformGuide(){
 if(!admin||!state?.endpoint)return;const url=URL.createObjectURL(new Blob([platformGuideDocument(state.endpoint)],{type:'text/html;charset=utf-8'}));
 try{const anchor=document.createElement('a');anchor.href=url;anchor.download='Harbor-平台说明.html';anchor.click();toast('平台文档已交给浏览器下载');}finally{setTimeout(()=>URL.revokeObjectURL(url),1000);}
}
function downloadAccessGuide(){
 if(!admin||!state?.endpoint)return;const blob=new Blob([accessGuideDocument(state.endpoint)],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob);
 try{const anchor=document.createElement('a');anchor.href=url;anchor.download='Harbor-接入说明.html';anchor.click();toast('接入文档已交给浏览器下载');}finally{setTimeout(()=>URL.revokeObjectURL(url),1000);}
}
function imageGuide(endpoint){
  const download=JSON.stringify(endpoint.replace(/\/$/,'')+'/codex/image-mcp.mjs');
  const windows=`Invoke-WebRequest -UseBasicParsing ${download} -Headers @{Authorization="Bearer $env:HARBOR_API_KEY"} -OutFile "$env:USERPROFILE\\.codex\\harbor-image-mcp.mjs"`;
  const linux=`curl --fail --silent --show-error -H "Authorization: Bearer $HARBOR_API_KEY" ${download} -o "$HOME/.codex/harbor-image-mcp.mjs"`;
  const config=`[mcp_servers.harbor_image]
command = "node"
args = ['C:\\Users\\YOUR_USER\\.codex\\harbor-image-mcp.mjs', 'C:\\Work\\YOUR_WORKSPACE']
env_vars = ["HARBOR_API_KEY"]
tool_timeout_sec = 600

[mcp_servers.harbor_image.env]
HARBOR_BASE_URL = ${JSON.stringify(endpoint)}`;
  return `<div class="panel-body"><p>原员工 Key 仍可使用，无需 OPENAI_API_KEY。每台客户端需单独安装图片 MCP；仅升级网关或新开聊天不会自动添加工具。</p><ol class="guide-list"><li>安装 Node.js 24，确认 node --version；在客户端进程中加载现有 HARBOR_API_KEY。</li><li>下载脚本到实际 CODEX_HOME（默认用户目录下的 .codex）；以下默认路径的父目录须已存在。</li></ol><label>Windows PowerShell</label><pre class="code">${esc(windows)}</pre><label>WSL / Linux</label><pre class="code">${esc(linux)}</pre><p>将下面配置合并到用户 config.toml，已有同名表时更新，不重复添加。把两个路径换成脚本和允许读写图片的工作区绝对路径；WSL 使用 Linux 路径。桌面应用找不到 node 时，填写 Node 24 可执行文件的绝对路径。</p><pre class="code">${esc(config)}</pre><p>完全退出并重启 Codex，再新建会话，确认 harbor_image 已连接、image_generate 工具可用。可以先运行 codex mcp list 检查注册；注册成功仍需实际调用验证。</p><p>生成：“用 Harbor 图片工具生成蓝色圆形，保存到 generated.png。”编辑：“把 generated.png 的圆形改成红色，保存到 edited.png。”输出路径必须在工作区内且文件尚不存在；检查图片可打开，并核对网关调用记录。</p><p>若仍提示“没有 image2 工具”或“缺少 OPENAI_API_KEY”，先检查是否加载了 harbor_image、Node 路径、工作区和环境变量；不要因此申请独立 API Key。超时或取消可能已消耗订阅额度，不自动重试。</p><p class="hint">远程连接请使用 HTTPS。停用时移除 MCP 配置并重启客户端。</p></div>`;
}
