let loginPoll,loginAccount='',loginView=0;
let dialogNeedsCleanup=false;
function modal(html,wide=false){if(!admin)return;if(dialogNeedsCleanup)close({keepOpen:$('#modal').open});dialogNeedsCleanup=true;dialogVersion++;$('#modal').classList.remove('member-dialog','extra-dialog','account-dialog','session-dialog');$('#modal').classList.toggle('wide',wide);$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal-content').scrollTop=0;}
function close({keepOpen=false}={}){if(!dialogNeedsCleanup&&!keepOpen&&!$('#modal').open)return;dialogNeedsCleanup=keepOpen;accountManagementId='';pricingView=null;pricingDialogVersion=0;stopExtraView();stopPackageViews();stopRecordingDialogs();stopDeviceViews();typeHistoryView?.controller.abort();typeHistoryView=null;fixedMemberChoice=null;memberDetailView?.controller.abort();memberDetailView=null;memberBatchView?.controller.abort();memberBatchView=null;typeController?.abort();typeController=null;typeEditor=null;stopPlanningPreview();stopHandoffView();recordingDetail?.controller?.abort();recordingDetail=null;memberLimitEditor=null;clearTimeout(loginPoll);loginAccount='';loginView++;dialogVersion++;requestDetailId='';historyListView=null;if(!keepOpen){keyRenewalSelection.clear();if($('#modal').open)$('#modal').close();}$('#modal-content').innerHTML='';}
function validDeviceLogin(value){try{const u=new URL(value.verificationUrl);return value.type==='device'&&u.origin==='https://auth.openai.com'&&u.pathname==='/codex/device'&&!u.search&&!u.hash&&!u.username&&!u.password&&/^[A-Z0-9-]{4,32}$/.test(value.userCode);}catch{return false;}}
function loginDialog(account,value){
  modal(`<h2>${esc(account.name)} · 官方登录</h2><p class="hint">在官方页面登录你的 ChatGPT 账号，再输入下面的一次性验证码。仅授权你刚刚发起的登录；验证码请勿分享。</p><div class="secret" id="device-code"></div><p class="hint">若新窗口未打开，可点击下方链接。设备码登录需在 ChatGPT 安全设置或工作区权限中启用。</p><div class="actions"><a class="primary" id="device-link" target="_blank" rel="noopener noreferrer">打开官方授权页面</a></div><p class="hint" id="login-status">等待官方授权，最多 10 分钟…</p><div class="dialog-actions">${button('cancel-login','取消登录','secondary',account.id)}${button('close','稍后继续','secondary')}</div>`);
  $('#device-code').textContent=value.userCode;$('#device-link').href=value.verificationUrl;
  loginAccount=account.id;const view=loginView,epoch=authEpoch;
  async function poll(){
    try{
      const current=await api('/api/admin/accounts/'+account.id+'/login');
      if(!admin||epoch!==authEpoch||view!==loginView||loginAccount!==account.id)return;
      if(current.state!=='login'){close();await refresh();return toast(current.state==='ready'?'账号已连接':current.message||'官方登录未完成，请重试');}
      if(current.expiresAt&&current.expiresAt<=Date.now()){$('#device-code').textContent='验证码已过期';$('#device-link').removeAttribute('href');$('#login-status').textContent='请取消后重新登录';return;}
      loginPoll=setTimeout(poll,2000);
    }catch(e){if(admin&&epoch===authEpoch&&view===loginView){$('#device-code').textContent='';$('#device-link').removeAttribute('href');$('#login-status').textContent=e.message;}}
  }
  loginPoll=setTimeout(poll,2000);
}
async function platformLoginFlow(identifier){
 const epoch=authEpoch;modal('<h2>正在获取平台授权…</h2><p class="hint">请稍候，或关闭后重试。</p>');const initial=dialogVersion;
 try{const value=await api('/api/admin/platform/accounts/'+identifier+'/login','POST',{});if(!admin||epoch!==authEpoch||initial!==dialogVersion)return;
 const url=new URL(value.verificationUrl);if(url.protocol!=='https:'||url.hostname!=='copilot.tencent.com'||url.username||url.password)throw Error('平台授权地址无效');
 modal(`<h2>WorkBuddy 官方登录</h2><p class="hint">在官方页面完成授权；平台不收集账号密码。</p><a id="platform-login-link" class="primary" target="_blank" rel="noopener noreferrer">打开官方授权页面</a><p id="platform-login-status" class="hint">等待授权，最多10分钟…</p><div class="dialog-actions">${button('platform-cancel-login','取消登录','secondary',identifier)}${button('close','稍后继续','secondary')}</div>`);$('#platform-login-link').href=url.href;const view=dialogVersion;
 async function poll(){try{const current=await api('/api/admin/platform/accounts/'+identifier+'/login');if(!admin||epoch!==authEpoch||view!==dialogVersion)return;if(current.state!=='login'){close();await refresh();return toast(current.state==='ready'?'平台已连接':current.message||'授权未完成');}loginPoll=setTimeout(poll,2000);}catch(error){if(admin&&epoch===authEpoch&&view===dialogVersion)$('#platform-login-status').textContent=error.message;}}
 loginPoll=setTimeout(poll,2000);
 }catch(error){if(admin&&epoch===authEpoch&&initial===dialogVersion)modal(`<h2>平台登录未启动</h2><p>${esc(error.message)}</p><div class="dialog-actions">${button('close','关闭','secondary')}</div>`);}
}
async function loginAccountFlow(identifier){
  const account=state.accounts.find(x=>x.id===identifier),epoch=authEpoch;let popup;
  if(account.kind==='codex')try{popup=window.open('about:blank','_blank');if(popup)popup.opener=null;}catch{}
  modal('<h2>正在获取官方授权…</h2>');
  const view=loginView;
  try{
    const result=await api('/api/admin/accounts/'+identifier+'/login','POST',{});
    if(!admin||epoch!==authEpoch||view!==loginView){popup?.close();return;}
    if(result.type==='browser'){popup?.close();close();await refresh();return toast('请在运行 Harbor 的本机浏览器完成官方登录');}
    if(!validDeviceLogin(result))throw Error('官方授权信息无效，请重新登录');
    loginDialog(account,result);if(popup&&!popup.closed)popup.location.replace(result.verificationUrl);
    await refresh();
  }catch(e){popup?.close();if(admin&&epoch===authEpoch&&view===loginView){modal(`<h2>官方登录未能启动</h2><div class="inline-error">${esc(e.message)}</div><div class="dialog-actions">${button('cancel-login','取消登录','secondary',identifier)}${button('close','关闭','secondary')}</div>`);}throw e;}
}
