      try{await api('/api/admin/sessions/'+view.id+'/handoffs','POST',{account_id:target,expected_route_version:binding.route_version,...(waiting?{replace_handoff_id:record.id}:{})},'',view.controller.signal);if(!currentHandoff(view))return;view.busy=false;view.mode='status';view.record=null;view.notice='转移已登记，以实际完成结果为准；关闭弹窗不会取消已登记操作。';await loadHandoff(view);}
