      if(!typeCurrent(view)||view.busy)return;const type=catalog.types.find(row=>row.id===form.get('batch_type'));if(!type)throw Error('请选择目标类型');view.busy=true;try{const result=await api('/api/admin/member-config-batches/preview','POST',{scope,type_id:type.id,expected_type_version:type.version,models:form.get('batch_models')==='apply',limits:form.get('batch_limits')==='apply',classify:form.get('batch_classify')==='apply',overwrite_exceptions:form.get('batch_overwrite')==='overwrite'},'',view.controller.signal);if(typeCurrent(view))await openMemberBatch(result.id);}catch(error){if(typeCurrent(view))throw error;}finally{view.busy=false;}
