function showRecordingRetentionPreview(plan){modal('<h2>确认正文保留期影响</h2><div id="recording-retention-content"></div>',true);const view={epoch:authEpoch,dialog:dialogVersion,controller:new AbortController(),plan,data:null,busy:false,error:'',conflicted:false};recordingRetentionView=view;renderRecordingRetention(view);}
