 try{const params=new URLSearchParams({member_id:view.memberId,page:view.page,page_size:dialogPageSize('devices')});if(view.keyId)params.set('key_id',view.keyId);if(view.state)params.set('state',view.state);const value=await api('/api/admin/devices?'+params,'GET',undefined,'',view.controller.signal);if(!deviceCurrent(view))return;if(!Array.isArray(value.rows)||!value.summary||!value.pagination)throw Error('设备目录响应无效');view.data=value;view.page=value.pagination.page;view.error='';}
