function renderDevices(view){
 if(!deviceCurrent(view))return;const data=view.data,disabled=view.loading||view.busy||!!view.error;
 $('#devices-content').innerHTML=`<div class="member-section-heading"><h3>${view.keyId?'Key 可用设备':'员工设备目录'}</h3>${button('device-return-member','返回员工','secondary',view.memberId)}</div><p class="hint">${data?deviceSummary(data.summary):'正在读取设备…'}。登记设备与近7天实际使用分别统计，不按来源IP推断设备。</p>${view.error?`<p class="notice warn">${esc(view.error)}；上次快照仅供核对，请刷新后操作。</p>`:''}<div class="toolbar"><select id="device-state" aria-label="设备状态"><option value="">全部状态</option>${Object.entries(deviceStates).map(([value,label])=>`<option value="${value}" ${value===view.state?'selected':''}>${label}</option>`).join('')}</select>${button('device-reload','刷新','secondary','',view.loading||view.busy)}${button('device-invite','邀请登记设备','primary','',disabled)}${data?.member?button('device-policy','员工接入策略：'+(data.member.device_mode==='enforced'?'强制设备认证':'兼容模式'),'secondary','',disabled):''}${view.keyId?button('device-key-policy','设置此Key设备范围','secondary',view.keyId,disabled):''}</div><div class="device-list">${(data?.rows||[]).map(row=>`<article class="member-key-card"><div class="member-section-heading"><h3>${esc(row.name)}</h3><span class="badge ${row.state==='approved'?'':'off'}">${esc(deviceStates[row.state]||row.state)}${row.pending_renewal?' · 待续期批准':''}</span></div>${deviceFingerprint(row)}<p>${esc(row.system)} · ${row.hardware_state==='reported'?'硬件已报告':row.hardware_state==='credentials_only'?'仅凭据认证（硬件降级）':'硬件不可用'}<br>凭据代次 ${fmt(row.credential_generation)} · ${row.certificate_expires?'证书到期 '+beijingDate(row.certificate_expires):'尚无证书'}${row.credential_generation&&!row.certificate_valid?' · 当前不可用':''}</p><p class="hint">近7天 ${fmt(row.request_count)} 次请求；最近使用 ${date(row.last_seen)}；${row.verified_request_at?'已完成真实调用验证':'尚未完成真实调用验证'}<br>可用Key：${row.allowed_key_ids===null?'员工所有Key（仍受各Key设备范围限制）':fmt(row.allowed_key_ids?.length)+' 个'}</p><div class="actions">${button('device-rename','改名','text-button',row.id,disabled)}${row.state==='pending'||row.state==='needs_review'||row.pending_renewal?button('device-approve',row.state==='needs_review'?'硬件复核':'批准登记／续期','secondary',row.id,disabled):''}${['approved','disabled'].includes(row.state)?button('device-toggle',row.state==='approved'?'停用设备':'恢复设备','text-button',row.id,disabled):''}${['approved','disabled','needs_review'].includes(row.state)?button('device-replace','换机邀请','text-button',row.id,disabled):''}${row.state==='approved'&&!row.pending_renewal?button('device-renew','续期邀请','text-button',row.id,disabled):''}${row.pending_renewal?button('device-cancel-renewal','取消待续期','text-button danger',row.id,disabled):''}</div></article>`).join('')||empty(data?'没有符合条件的设备':'正在读取…')}</div>${data?`<div class="pager">${button('device-page','上一页','secondary',view.page-1,disabled||view.page<=1)}<span>第 ${view.page}／${data.pagination.totalPages} 页 · 共 ${fmt(data.pagination.total)} 台</span>${button('device-page','下一页','secondary',view.page+1,disabled||view.page>=data.pagination.totalPages)}${pageSizeControl('devices',dialogPageSize('devices'))}</div>`:''}`;
 $('#device-state').disabled=view.loading||view.busy;$('#device-state').onchange=event=>{if(view.loading||view.busy)return;view.state=event.target.value;view.page=1;view.data=null;void loadDevices(view);};
}
async function deviceMutation(view,path,method,body){
 if(!deviceCurrent(view)||view.loading||view.busy)return;view.busy=true;renderDevices(view);
 try{await api(path,method,body,'',view.controller.signal);if(!deviceCurrent(view))return;view.error='';}
 catch(error){if(deviceCurrent(view)){toast(error.message);view.error=error.message;}}
 finally{view.busy=false;if(deviceCurrent(view))await loadDevices(view);}
}
function deviceEditor(view,title,fields,submit){
 const context={memberId:view.memberId,keyId:view.keyId,page:view.page,state:view.state};let edit;
 formModal(title,'修改只影响对应员工或设备；已派发请求继续完成。',fields,async form=>{if(!typeCurrent(edit)||edit.busy)return;edit.busy=true;try{await submit(form,edit);if(typeCurrent(edit))await openDevices(context.memberId,context.keyId,context);}catch(error){if(typeCurrent(edit))throw error;}finally{edit.busy=false;}});
 edit={epoch:authEpoch,dialog:dialogVersion,controller:new AbortController(),busy:false};typeController=edit.controller;
}
function editDevice(action,identifier){
 const view=deviceView;if(!deviceCurrent(view)||view.loading||view.busy||view.error)return;const row=view.data?.rows.find(item=>item.id===identifier),path='/api/admin/devices/'+identifier;
 if(action==='device-copy-fingerprint'&&row){if(typeof row.fingerprint==='string'&&/^[a-f0-9]{64}$/.test(row.fingerprint))return copyKey(row.fingerprint,'设备指纹').then(()=>toast('设备指纹已复制'));return;}
 if(action==='device-rename'&&row)return deviceEditor(view,'修改设备名称',`<label>设备名称<input name="name" maxlength="80" required value="${esc(row.name)}"></label>`,(form,edit)=>api(path,'PATCH',{name:form.get('name'),expected_version:row.version},'',edit.controller.signal));
 if(action==='device-approve'&&row)return deviceEditor(view,'批准设备',`<p>设备：${esc(row.name)}；${esc(row.system)}。${row.replaces_device_id?'批准后原设备及其旧凭据立即失效。':''}</p><label>硬件核验方式<select name="hardware"><option value="reported">核对已报告硬件</option><option value="credentials">明确接受仅凭据认证（硬件降级）</option></select></label><p class="hint">缺少硬件指纹时必须明确选择降级；系统不会将凭据认证显示为硬件认证。</p>`,(form,edit)=>api(path+'/approve','POST',{expected_version:row.version,credentials_only:form.get('hardware')==='credentials'},'',edit.controller.signal));
 if(action==='device-toggle'&&row)return deviceMutation(view,path,'PATCH',{expected_version:row.version,enabled:row.state!=='approved'});
 if(action==='device-cancel-renewal'&&row)return deviceMutation(view,path+'/cancel-renewal','POST',{expected_version:row.version});
 if(action==='device-policy'&&view.data?.member){const member=view.data.member;return deviceEditor(view,'员工设备接入策略',`<label>接入方式<select name="mode"><option value="compatible" ${member.device_mode==='compatible'?'selected':''}>兼容模式：允许未登记客户端</option><option value="enforced" ${member.device_mode==='enforced'?'selected':''}>强制设备认证：必须通过设备门禁</option></select></label><p class="hint">启用强制模式前，必须已有批准设备并完成一次真实模型调用。前端关闭或回退不会解除服务器门禁。</p>`,(form,edit)=>api('/api/admin/members/'+view.memberId+'/device-policy','PATCH',{mode:form.get('mode'),expected_version:member.device_policy_version},'',edit.controller.signal));}
 if(['device-invite','device-replace','device-renew'].includes(action)){
  if(action!=='device-invite'&&!row)return;const memberId=view.memberId,keyId=view.keyId;
  return deviceEditor(view,action==='device-replace'?'创建换机邀请':action==='device-renew'?'创建设备续期邀请':'创建设备邀请',`<p>${row?'设备：'+esc(row.name):'邀请新的员工设备'}；有效期1小时。邀请仅在生成后当前弹窗显示，请通过可信方式交付。</p><label>可用Key范围<select name="scope"><option value="all">员工所有Key</option>${keyId?'<option value="key" selected>仅当前Key</option>':''}</select></label>`,async(form,edit)=>{
   const result=await api('/api/admin/device-invitations','POST',{member_id:memberId,allowed_key_ids:form.get('scope')==='key'?[keyId]:null,...(action==='device-replace'?{replaces_device_id:identifier}:action==='device-renew'?{renews_device_id:identifier}:{})},'',edit.controller.signal);if(!typeCurrent(edit))return;
   // Invite credentials exist only in this dialog closure and never in durable page state.
   modal(`<h2>设备邀请已生成</h2><p class="hint">有效至 ${beijingDate(result.expires)}。关闭后无法再次查看，请勿放入工单或日志。</p><pre id="device-invitation" class="code"></pre><div class="dialog-actions">${button('device-copy-invite','复制邀请','primary')}${button('device-return-member','返回员工','secondary',memberId)}</div>`);$('#device-invitation').textContent=JSON.stringify({invitation:result.token,scope:result.scope});$('#device-invitation').dataset.copyValue=$('#device-invitation').textContent;
  });
 }
}
async function editKeyDevicePolicy(){
 const source=deviceView;if(!deviceCurrent(source)||!source.keyId||source.loading||source.busy||source.error)return;
 const memberId=source.memberId,keyId=source.keyId;modal('<h2>设置Key设备范围</h2><p>正在读取当前Key策略…</p>',true);const view={epoch:authEpoch,dialog:dialogVersion,controller:new AbortController()};typeController=view.controller;
 try{const result=await api('/api/admin/members/'+memberId+'/keys?page=1&page_size=100','GET',undefined,'',view.controller.signal);if(!typeCurrent(view))return;let key=result.rows.find(row=>row.id===keyId);let page=1;while(!key&&page<result.pagination.totalPages){const next=await api('/api/admin/members/'+memberId+'/keys?page='+(++page)+'&page_size=100','GET',undefined,'',view.controller.signal);if(!typeCurrent(view))return;key=next.rows.find(row=>row.id===keyId);}if(!key)throw Error('Key已移除');
  const selection=new Set(key.device_ids||[]);let current=1,data,busy=false,scopeError='',conflicted=false;
  const render=()=>{if(!typeCurrent(view))return;$('#modal-content').innerHTML=`<h2>Key设备范围</h2>${scopeError?`<p class="notice warn">${esc(scopeError)}</p>${button('device-scope-reload-policy','重新读取Key策略（保留草稿）','secondary')}`:''}<p class="hint">先满足员工设备策略与设备可用Key范围，再应用此额外收窄。跨页已选 ${selection.size} 台；只显示已批准设备。</p><label>范围<select id="key-device-mode"><option value="all" ${key.device_ids===null?'selected':''}>不额外收窄</option><option value="selected" ${key.device_ids!==null?'selected':''}>只允许已选设备（空表示禁止所有设备）</option></select></label><p class="hint">当前固定选择：${[...selection].map(id=>button('device-scope-remove','移除 '+esc(id.slice(-8)),'text-button',id)).join('')||'无'}</p>${data.rows.map(row=>`<label><input type="checkbox" data-action="device-scope-select" data-id="${esc(row.id)}" ${selection.has(row.id)?'checked':''}>${esc(row.name)} · ${esc(row.system)}</label>`).join('')||empty('暂无已批准设备')}<div class="pager">${button('device-scope-page','上一页','secondary',current-1,current<=1)}<span>${current}／${data.pagination.totalPages}</span>${button('device-scope-page','下一页','secondary',current+1,current>=data.pagination.totalPages)}${pageSizeControl('device-scope',dialogPageSize('device-scope'),busy)}</div><div class="dialog-actions">${button('device-scope-save','保存Key设备范围','primary','',conflicted)}${button('device-return-member','返回员工','secondary',memberId)}</div>`;$('#key-device-mode').onchange=event=>{key.device_ids=event.target.value==='all'?null:[...selection];};};
  const load=async number=>{if(busy||!typeCurrent(view))return;busy=true;if(data)render();try{const value=await api('/api/admin/devices?'+new URLSearchParams({member_id:memberId,state:'approved',page:number,page_size:dialogPageSize('device-scope')}),'GET',undefined,'',view.controller.signal);if(typeCurrent(view)){data=value;current=data.pagination.page;render();}}catch(error){if(typeCurrent(view)){scopeError=error.message;if(data)render();else throw error;}}finally{busy=false;if(typeCurrent(view)&&data)render();}};
  view.scopeAction=async(action,id)=>{
   if(busy||!typeCurrent(view))return;
   try{
    if(action==='device-scope-select'){if(!data.rows.some(row=>row.id===id))return;selection.has(id)?selection.delete(id):selection.add(id);render();}
    if(action==='device-scope-remove'){selection.delete(id);render();}
    if(action==='device-scope-page')await load(Number(id));
    if(action==='device-scope-reload-policy'){
     busy=true;let currentKey,page=1,total=1;
     do{const result=await api('/api/admin/members/'+memberId+'/keys?page='+page+'&page_size=100','GET',undefined,'',view.controller.signal);if(!typeCurrent(view))return;currentKey=result.rows.find(row=>row.id===keyId);total=result.pagination.totalPages;page++;}while(!currentKey&&page<=total);
     if(!currentKey)throw Error('Key已移除');key.device_policy_version=currentKey.device_policy_version;conflicted=false;scopeError='已读取新版本；服务器当前范围：'+(currentKey.device_ids===null?'不额外收窄':currentKey.device_ids.length+' 台设备')+'。你的选择已保留，请核对后重新保存。';render();
    }
    if(action==='device-scope-save'){
     if(conflicted)return;busy=true;await api('/api/admin/keys/'+keyId+'/devices','PATCH',{expected_version:key.device_policy_version,device_ids:key.device_ids===null?null:[...selection]},'',view.controller.signal);if(typeCurrent(view))await openDevices(memberId,keyId);
    }
   }catch(error){if(typeCurrent(view)){scopeError=error.message;if(error.status===409)conflicted=true;render();}}
   finally{busy=false;if(typeCurrent(view))render();}
  };view.scopeBusy=()=>busy;view.renderScope=render;deviceView={...view,keyScope:true};await load(1);
 }catch(error){if(typeCurrent(view)){$('#modal-content').innerHTML=`<h2>无法编辑设备范围</h2><p>${esc(error.message)}</p>${button('device-return-member','返回员工','secondary',memberId)}`;}}
}
function currentAccessBatch(view){return accessBatchView===view&&typeCurrent(view);}
const accessResultLabels={preview:'待确认',queued:'排队执行',completed:'已完成',cancelled:'已取消',pending:'待执行',success:'已完成',unchanged:'无需修改',skipped:'跳过',failed:'失败'};
const accessReasons={member_removed:'员工已移除',state_changed:'状态已变化',renewal_target_expired:'目标续期时间已过',admin_cancelled:'管理员取消',execution_interrupted:'执行中断',operation_failed:'操作失败'};
async function previewMemberAccess(enabled){
 if(!state?.capabilities?.memberActions||!memberSelection.size)return;const selected=[...memberSelection.values()];let view;
 formModal(enabled?'批量恢复员工访问':'批量停用员工访问',`固定已选 ${selected.length} 名员工。员工启停不改变各Key自身的启停状态；已经派发的请求继续完成。`, '<p>下一步生成逐人预览，确认执行前不会修改员工。执行时发生版本变化的对象跳过。</p>',async()=>{if(!typeCurrent(view)||view.busy)return;view.busy=true;try{const result=await api('/api/admin/member-action-batches/preview','POST',{kind:'member_access',enabled,member_ids:selected.map(row=>row.id),...(selected.every(row=>Number.isSafeInteger(row.access_version))?{member_versions:selected.map(({id,access_version,usage_type_version,defaults_version})=>({id,access_version,usage_type_version,defaults_version}))}:{})},'',view.controller.signal);if(typeCurrent(view))await openAccessBatch(result.id);}catch(error){if(typeCurrent(view))throw error;}finally{view.busy=false;}});view={epoch:authEpoch,dialog:dialogVersion,controller:new AbortController(),busy:false};typeController=view.controller;
}
function previewKeyRenewal(){
 if(!state?.capabilities?.memberActions||!keyRenewalSelection.size)return;const selected=[...keyRenewalSelection.values()];let view;
 formModal('续期选定Key',`固定 ${selected.length} 个 Key，仅延长有效期；永久Key及有效期更长的Key保持原状，不恢复停用Key，不清零用量。`,expirationFields,async form=>{if(!typeCurrent(view)||view.busy)return;view.busy=true;try{const result=await api('/api/admin/member-action-batches/preview','POST',{kind:'key_renewal',expires:expiresFrom(form),key_ids:selected.map(row=>row.id),...(selected.every(row=>Number.isSafeInteger(row.access_version)&&Number.isSafeInteger(row.model_policy_version))?{key_versions:selected.map(({id,access_version,model_policy_version})=>({id,access_version,model_policy_version}))}:{})},'',view.controller.signal);if(typeCurrent(view))await openAccessBatch(result.id);}catch(error){if(typeCurrent(view))throw error;}finally{view.busy=false;}});view={epoch:authEpoch,dialog:dialogVersion,controller:new AbortController(),busy:false};typeController=view.controller;
}
async function openAccessBatch(id){modal('<h2>访问操作预览与结果</h2><div id="access-batch-content"></div>',true);const view={id,epoch:authEpoch,dialog:dialogVersion,controller:new AbortController(),record:null,page:0,cursors:[0],loading:false,busy:false,error:''};accessBatchView=view;await loadAccessBatch(view);}
function renderAccessBatch(view){
 if(!currentAccessBatch(view))return;const record=view.record,disabled=view.loading||view.busy||!!view.error;
 if(!record){$('#access-batch-content').innerHTML=`<p>${esc(view.error||'正在读取固定目标与结果…')}</p>${button('access-batch-refresh','重新读取','secondary')}`;return;}
 const terminal=['completed','cancelled'].includes(record.status),counts=record.counts||{};
 $('#access-batch-content').innerHTML=`<p><strong>${esc(accessResultLabels[record.status]||record.status)}</strong> · ${record.direction==='undo'?'撤销预览／结果':record.operation.kind==='key_renewal'?'续期选定Key':record.operation.enabled?'恢复员工访问':'停用员工访问'}</p><p class="hint">${Object.entries(counts).map(([key,count])=>esc(accessResultLabels[key]||key)+' '+fmt(count)).join(' · ')}。执行受理不等于完成；关闭弹窗不取消已受理任务，可从近7天访问操作记录重开。${record.execution_failed?'后台执行中断，可只重试失败项。':''}</p>${view.error?`<p class="notice warn">${esc(view.error)}。上次快照仅供核对，请重新读取。</p>`:''}<div class="member-batch-items">${record.items.map(item=>`<article class="member-key-card"><h3>${esc(item.member_name)} <span class="badge">${esc(accessResultLabels[item.status]||item.status)}</span></h3>${record.operation.kind==='member_access'?`<p>员工访问：${item.before_state.member.enabled?'启用':'停用'} → ${item.desired_state.member.enabled?'启用':'停用'}；各Key自身启停保持。</p>`:`<p>固定选定 ${fmt(item.selected_keys?.length)} 个 Key；未选Key不修改。</p>${item.desired_state.keys.filter(key=>item.selected_keys.includes(key.id)).map(key=>{const before=item.before_state.keys.find(row=>row.id===key.id);return `<p class="hint">Key ${esc(key.id.slice(-8))}：${before?.expires?beijingDate(before.expires):'永久'} → ${key.expires?beijingDate(key.expires):'永久'}</p>`;}).join('')}`}<p class="hint">${item.reason?esc(accessReasons[item.reason]||item.reason):''}${item.notes?.length?' · '+esc(item.notes.map(note=>(typeof note==='object'?'Key '+note.key_id.slice(-8)+'：':'')+({already_permanent:'已永久有效',same_expiry:'有效期相同',already_longer:'原有效期更长',make_permanent:'改为永久',extend:'延长有效期'}[typeof note==='string'?note:note.reason]||'待核对')).join('；')):''}</p></article>`).join('')}</div><div class="pager">${button('access-batch-page','上一页','secondary','prev',disabled||view.page===0)}<span>第 ${view.page+1} 页</span>${button('access-batch-page','下一页','secondary','next',disabled||!record.has_more)}${pageSizeControl('access-batch',dialogPageSize('access-batch'))}</div><div class="dialog-actions">${record.status==='preview'?button('access-batch-execute','确认执行固定目标','primary','',disabled||record.expires<=Date.now()):''}${['preview','queued'].includes(record.status)?button('access-batch-cancel','取消剩余操作','text-button danger','',disabled):''}${terminal&&counts.failed||record.execution_failed?button('access-batch-retry','只重试失败项（先预览）','secondary','',disabled):''}${terminal&&record.direction!=='undo'&&counts.success?button('access-batch-undo','安全撤销成功项（先预览）','secondary','',disabled):''}${button('access-batch-refresh','刷新结果','secondary','',view.loading||view.busy)}</div>`;
}
async function loadAccessBatch(view,automatic=false){
 if(!currentAccessBatch(view)||view.loading||view.busy)return;view.loading=true;if(!automatic)renderAccessBatch(view);
 try{const result=await api('/api/admin/member-action-batches/'+view.id+'?after='+view.cursors[view.page]+'&limit='+dialogPageSize('access-batch'),'GET',undefined,'',view.controller.signal);if(!currentAccessBatch(view))return;if(result.id!==view.id||!Array.isArray(result.items)||!result.counts)throw Error('访问批次响应无效');view.record=result;view.error='';if(['completed','cancelled'].includes(result.status)&&!view.synced){if(!await refresh(false))throw Error('员工列表尚未同步，请刷新结果重试');if(currentAccessBatch(view))view.synced=true;}}
 catch(error){if(currentAccessBatch(view))view.error=error.message;}
 finally{view.loading=false;if(currentAccessBatch(view))renderAccessBatch(view);}
}
async function actAccessBatch(action){const view=accessBatchView;if(!currentAccessBatch(view)||view.loading||view.busy||view.error)return;view.busy=true;renderAccessBatch(view);try{const result=await api('/api/admin/member-action-batches/'+view.id+(action==='cancel'?'':'/'+action),action==='cancel'?'DELETE':'POST',action==='cancel'?undefined:{},'',view.controller.signal);if(!currentAccessBatch(view))return;if(['retry','undo'].includes(action)){if(result.no_retry_needed){toast('没有需要重试的失败项');}else return await openAccessBatch(result.id);}view.busy=false;await loadAccessBatch(view);}catch(error){if(currentAccessBatch(view))view.error=error.message;}finally{view.busy=false;if(currentAccessBatch(view))renderAccessBatch(view);}}
async function openAccessHistory(before=''){
 modal('<h2>近7天访问操作记录</h2><div id="access-history-content">正在读取…</div>',true);const view={epoch:authEpoch,dialog:dialogVersion,controller:new AbortController()};typeController=view.controller;historyListView={...view,kind:'access-history'};
 try{const result=await api('/api/admin/member-action-batches?'+new URLSearchParams({limit:dialogPageSize('access-history'),...(before?{before}:{})}),'GET',undefined,'',view.controller.signal);if(!typeCurrent(view))return;$('#access-history-content').innerHTML=`${result.items.map(row=>`<article class="member-key-card"><p>${beijingDate(row.created)} · ${esc(accessResultLabels[row.status]||row.status)} · ${row.operation.kind==='key_renewal'?'Key续期':row.operation.enabled?'恢复员工':'停用员工'} · ${fmt(row.members)} 人</p>${button('access-batch-open','查看固定目标与结果','secondary',row.id)}</article>`).join('')||empty('暂无记录')}<div class="pager">${before?button('access-history','返回最新','secondary'):''}${result.has_more?button('access-history','更早一页','secondary',result.before):''}${pageSizeControl('access-history',dialogPageSize('access-history'))}</div>`;}catch(error){if(typeCurrent(view))$('#access-history-content').textContent=error.message;}
}

async function checkKey(){testKey=$('#test-key').value.trim();const key=testKey,epoch=authEpoch;try{const m=await api('/api/me','GET',undefined,key);if(epoch!==authEpoch||tab!=='playground'||$('#test-key')?.value.trim()!==key)return;$('#my-quota').textContent=`${m.name}：此 Key 近7天 ${referenceTotal(m.keyStandard)} 参考消耗USD${referenceCoverage(m.keyStandard)?' · '+referenceCoverage(m.keyStandard):''}`;const directory=await api('/v1/platform/models','GET',undefined,key);if(epoch!==authEpoch||tab!=='playground'||$('#test-key')?.value.trim()!==key)return;platformModels=directory.data.map(m=>m.id);for(const model of platformModels){if(![...$('#chat-model').options].some(o=>o.value===model)){const option=document.createElement('option');option.value=model;option.textContent=platformModelLabel(model);$('#chat-model').append(option);}}}catch(e){if(epoch===authEpoch)toast(e.message);}}
async function sendChat(e){
  e.preventDefault();testKey=$('#test-key').value.trim();const content=$('#prompt').value.trim();
  if(!testKey)return toast('请填写员工 Key');if(!content||sending)return;
  const epoch=authEpoch;draft=content;sending=true;render();let appended=false;
  try{
    const member=await api('/api/me','GET',undefined,testKey);
    if(epoch!==authEpoch)return;
    if(chatOwner&&chatOwner!==member.id){chat=[];chatSession='';toast('已切换员工，自动新建会话');}
    chatOwner=member.id;chat.push({role:'user',content});appended=true;draft='';if(tab==='playground')render();
    const r=await api(chatModel.includes('/')?'/v1/platform/chat/completions':'/v1/chat/completions','POST',{model:chatModel,messages:chatModel.includes('/')?chat:chatSession?[chat.at(-1)]:chat,stream:false,...(chatSession?{session_id:chatSession}:{})},testKey);
    if(epoch!==authEpoch)return;
    if(r.context_reset)chat=[{role:'user',content}];chatSession=r.session_id;chat.push({role:'assistant',content:r.choices[0].message.content});toast((r.context_reset?'测试上下文已重置 · ':'完成 · ')+referenceTotal(r.harbor_standard_usage)+' Standard参考USD · '+referenceState(r.harbor_standard_usage?.state));
  }catch(err){if(epoch===authEpoch){if(appended)chat.pop();draft=content;toast(err.message+'；输入已保留');}}
  finally{sending=false;if(admin&&epoch===authEpoch)await refresh(false);if(tab==='playground'&&epoch===authEpoch)render();}
}

